-- FraudCast Phase 8: synthetic account-holder identities (names, Aadhaar, PAN). Safe to re-run.
-- Run after seed.sql. Every value is fictional. Aadhaar numbers start with 0/1 and fail the check digit;
-- PAN numbers use 'Z' as the holder-type letter. Neither can belong to a real person.
begin;
alter table accounts add column if not exists holder_name text;
alter table accounts add column if not exists aadhaar_synthetic text;
alter table accounts add column if not exists pan_synthetic text;
alter table accounts drop constraint if exists accounts_aadhaar_synthetic_chk;
alter table accounts add constraint accounts_aadhaar_synthetic_chk check (aadhaar_synthetic is null or aadhaar_synthetic ~ '^[01][0-9]{3} [0-9]{4} [0-9]{4}$');
alter table accounts drop constraint if exists accounts_pan_synthetic_chk;
alter table accounts add constraint accounts_pan_synthetic_chk check (pan_synthetic is null or pan_synthetic ~ '^[A-Z]{3}Z[A-Z][0-9]{4}[A-Z]$');
